module.exports = performance_monitor

function performance_monitor (ms = 1000) {
  const listeners = new Set()
  const state = {
    iid: null,
    sampling: false,
    last: performance.now(),
    net: { requests: 0, transferred: 0, decoded: 0 },
    lag: { current: 0, worst: 0, long: [], long_count: 0, worst_long: 0 }
  }
  const handlers = { resource: handle_resource, longtask: handle_longtask }
  setup_observer()

  const api = { run, end, on, off, sample }
  return api

  function setup_observer () {
    if (typeof PerformanceObserver === 'undefined') return
    const supported = PerformanceObserver.supportedEntryTypes || []
    const entry_types = ['resource', 'longtask'].filter(type => supported.includes(type))
    if (!entry_types.length) return
    try {
      const observer = new PerformanceObserver(observe)
      observer.observe({ entryTypes: entry_types })
    } catch {}
  }

  function observe (list) {
    for (const entry of list.getEntries()) handlers[entry.entryType]?.(entry)
  }

  function handle_resource (entry) {
    state.net.requests++
    state.net.transferred += entry.transferSize || 0
    state.net.decoded += entry.decodedBodySize || 0
  }

  function handle_longtask (entry) {
    state.lag.long.push({ start: entry.startTime, duration: entry.duration })
    state.lag.long_count++
    state.lag.worst_long = Math.max(state.lag.worst_long, entry.duration)
  }

  function on (listener) { listeners.add(listener) }
  function off (listener) { listeners.delete(listener) }

  function end () {
    if (state.iid) clearInterval(state.iid)
    state.iid = null
  }

  function run (listener) {
    end()
    if (listener) on(listener)
    state.last = performance.now()
    state.iid = setInterval(sample, ms)
  }

  function get_lag () {
    const now = performance.now()
    state.lag.current = Math.max(0, now - state.last - ms)
    state.lag.worst = Math.max(state.lag.worst, state.lag.current)
    state.last = now
    const long = state.lag.long.splice(0)
    return {
      current: state.lag.current,
      worst: state.lag.worst,
      long,
      long_count: state.lag.long_count,
      worst_long: state.lag.worst_long
    }
  }

  function get_heap () {
    const memory = performance.memory
    if (!memory) return null
    return {
      used: memory.usedJSHeapSize,
      total: memory.totalJSHeapSize,
      limit: memory.jsHeapSizeLimit
    }
  }

  async function get_user_agent_memory () {
    if (!performance.measureUserAgentSpecificMemory) return null
    try { return await performance.measureUserAgentSpecificMemory() } catch { return null }
  }

  async function get_storage () {
    if (!navigator.storage?.estimate) return null
    try { return await navigator.storage.estimate() } catch { return null }
  }

  async function sample () {
    if (state.sampling) return
    state.sampling = true
    try {
      const lag = get_lag()
      const heap = get_heap()
      const storage = await get_storage()
      const ua = await get_user_agent_memory()
      const stats = {
        time: Date.now(),
        memory: { heap, ua },
        storage,
        network: { ...state.net },
        lag
      }
      emit(stats)
      return stats
    } finally {
      state.sampling = false
    }
  }

  function emit (stats) {
    for (const listener of listeners) listener(stats)
    return stats
  }
}
